SELECT value FROM (WITH Months AS (SELECT DISTINCT DATE_TRUNC(TxnDate, MONTH) AS NRRMonth FROM `project-for-method-dw.revenue.TransLineFlattened` WHERE DATE_TRUNC(TxnDate, MONTH) < DATE_TRUNC(CURRENT_DATE(), MONTH) AND DATE_TRUNC(TxnDate, MONTH) >= '2024-01-01'), YearlyRevenue AS (SELECT m.NRRMonth, t.EntityRecordID, SUM(CASE WHEN DATE_TRUNC(t.TxnDate, MONTH) = DATE_SUB(m.NRRMonth, INTERVAL 12 MONTH) THEN t.SaaSAmount ELSE 0 END) AS P1Revenue, SUM(CASE WHEN DATE_TRUNC(t.TxnDate, MONTH) = m.NRRMonth THEN t.SaaSAmount ELSE 0 END) AS Revenue_NRRMonth, SUM(CASE WHEN DATE_TRUNC(t.TxnDate, MONTH) = DATE_SUB(m.NRRMonth, INTERVAL 12 MONTH) AND t.AccountFullName LIKE '%Prepay Expiry%' THEN t.SaaSAmount ELSE 0 END) AS OtherChurn FROM Months m JOIN `project-for-method-dw.revenue.TransLineFlattened` t ON t.TxnDate >= DATE_SUB(m.NRRMonth, INTERVAL 13 MONTH) AND t.TxnDate < DATE_ADD(m.NRRMonth, INTERVAL 1 MONTH) GROUP BY m.NRRMonth, t.EntityRecordID), Classified AS (SELECT NRRMonth, P1Revenue, OtherChurn, CASE WHEN Revenue_NRRMonth = 0 AND P1Revenue > 0 THEN P1Revenue ELSE 0 END AS ChurnedRevenue, CASE WHEN Revenue_NRRMonth > P1Revenue AND P1Revenue > 0 THEN Revenue_NRRMonth - P1Revenue ELSE 0 END AS UpgradeRevenue, CASE WHEN Revenue_NRRMonth < P1Revenue AND Revenue_NRRMonth > 0 THEN P1Revenue - Revenue_NRRMonth ELSE 0 END AS DowngradeRevenue FROM YearlyRevenue) SELECT FORMAT_DATE('%Y-%m', NRRMonth) AS period, ROUND(SAFE_DIVIDE(SUM(P1Revenue) + SUM(UpgradeRevenue) - SUM(ChurnedRevenue) - SUM(DowngradeRevenue), SUM(P1Revenue) - SUM(OtherChurn)) * 100, 2) AS value FROM Classified GROUP BY NRRMonth ORDER BY NRRMonth) WHERE CAST(period AS STRING) LIKE '2026-07%'